import sys; sys.path.append('/tmp')
from full_device_census import *

# Check all devices across E-201..E-204, E-211, E-231..E-233 that have Y > 1800 (near Entry Vestibule Y=2000..2813 or South wall aprons Y=2684..2813):
all_devs = []
for m, x, y in e201_drawn: all_devs.append(('E-201', m, *map_e201(x, y)))
for m, x, y in e202_drawn: all_devs.append(('E-202', m, *map_e202(x, y)))
for m, x, y in e203_drawn: all_devs.append(('E-203', m, *map_e203(x, y)))
for m, x, y in e204_drawn: all_devs.append(('E-204', m, *map_e204(x, y)))
for m, x, y in e211_drawn: all_devs.append(('E-211', m, *map_e211(x, y)))
for m, x, y in e231_devs:  all_devs.append(('E-231', m, *map_e231(x, y)[:2]))
for m, x, y in e232_devs:
    if m != 'UNRES': all_devs.append(('E-232', m, *map_e232(x, y)[:2]))
for m, x, y in e233_devs:
    if m != 'UNRES': all_devs.append(('E-233', m, *map_e233(x, y)[:2]))

for s, m, X, Y in all_devs:
    if m in ('R4', 'R6', 'R7', 'F4', 'F5', 'D1'): continue
    if Y > 1900:
        print(f'{s:5s} {m:3s} A102=({X:6.1f}, {Y:6.1f}) damp={str(is_damp(X,Y)):5s}')
"

