import fitz, glob
for p in sorted(glob.glob('/filesystem/final_batch4__electrical_task17_ec_0205_d100__blind/standards/*.pdf')):
    doc = fitz.open(p)
    for page_num, page in enumerate(doc, 1):
        txt = page.get_text()
        for kw in ['quad', 'Quad', 'QUAD', 'double duplex', 'two-gang', 'plaster ring']:
            if kw in txt:
                print(f'{p.split(\"/\")[-1]} p.{page_num} ({kw}):')
                for line in txt.splitlines():
                    if kw.lower() in line.lower():
                        print('  ', line)
